<script setup lang="ts">
import { ref, watch, computed } from 'vue';
import { useAuth } from '../stores/auth';
import { managementRequest } from '../api/management';
const props=defineProps<{cycles:any[]}>(), auth=useAuth();
const cycleId=ref(''), rows=ref<any[]>([]), selected=ref<any>(null), state=ref<any>(null), draft=ref<Record<string,any>>({}), busy=ref(false), loading=ref(false), notice=ref(''), department=ref(''), search=ref(''), filter=ref('ALL'), tab=ref('member');
let requestId=0;
const labels:Record<string,string>={strengths:'个人优势',improvements:'待提升方面',growth_suggestions:'成长建议',action_plan:'下月行动计划',traits:'成长特征',capability_features:'能力特征'};
const legacy:Record<string,string>={strengths:'个人优势',weaknesses:'待提升方面',suggestions:'成长建议',directions:'改进方向'};
const statusLabel:Record<string,string>={DRAFT:'待核对',CONFIRMED:'已展示',FAILED:'生成失败',GENERATING:'生成中',NONE:'待生成',UNKNOWN:'无权限或加载失败'};
const departments=computed(()=>[...new Set(rows.value.map(r=>r.department_name).filter(Boolean))]);
const filtered=computed(()=>rows.value.filter(r=>(!department.value||r.department_name===department.value)&&(!search.value||r.display_name?.includes(search.value.trim()))&&(filter.value==='ALL'||r.growthStatus===filter.value)));
const counts=computed(()=>({total:rows.value.length,pending:rows.value.filter(r=>r.growthStatus==='DRAFT').length,confirmed:rows.value.filter(r=>r.growthStatus==='CONFIRMED').length}));
const currentDraft=computed(()=>state.value?.items?.find((x:any)=>x.status==='DRAFT'));
watch(()=>props.cycles,()=>{if(!cycleId.value||!props.cycles.some(c=>c.id===cycleId.value))cycleId.value=props.cycles[0]?.id??'';},{immediate:true});
watch(cycleId,load,{immediate:true});
async function load(){const seq=++requestId;selected.value=null;state.value=null;rows.value=[];notice.value='';if(!cycleId.value)return;loading.value=true;try{const list=await managementRequest(`management/archives?cycleId=${encodeURIComponent(cycleId.value)}`);const results=await Promise.all(list.map(async(r:any)=>{try{const s=await managementRequest(`management/publications/${r.id}/growth`);const latest=s.items?.[0];return {...r,growthState:s,growthStatus:latest?.status??'NONE',updated:latest?.confirmed_at??latest?.created_at??r.published_at};}catch{return {...r,growthStatus:'UNKNOWN'};}}));if(seq!==requestId)return;rows.value=results;if(results.length)select(results[0]);}catch(e){if(seq===requestId)notice.value=String(e);}finally{if(seq===requestId)loading.value=false;}}
function select(r:any){selected.value=r;state.value=r.growthState??null;const item=state.value?.items?.find((x:any)=>x.status==='DRAFT')??state.value?.items?.find((x:any)=>x.status==='CONFIRMED');draft.value=JSON.parse(JSON.stringify(item?.draft_json??item?.confirmed_json??{}));}
async function refreshSelected(){if(!selected.value)return;const s=await managementRequest(`management/publications/${selected.value.id}/growth`);selected.value.growthState=s;selected.value.growthStatus=s.items?.[0]?.status??'NONE';selected.value.updated=s.items?.[0]?.confirmed_at??s.items?.[0]?.created_at??selected.value.published_at;select(selected.value);}
async function generate(){if(!selected.value)return;busy.value=true;notice.value='';try{await managementRequest(`management/publications/${selected.value.id}/growth/generate`,{});await refreshSelected();notice.value='草稿已生成，请核对后确认。';}catch(e){notice.value=String(e);try{await refreshSelected();}catch{}}finally{busy.value=false;}}
async function confirm(){if(!currentDraft.value)return;busy.value=true;notice.value='';try{await managementRequest(`management/growth/${currentDraft.value.id}/confirm`,draft.value);await refreshSelected();notice.value='已确认，成员端可查看本版本成长分析。';}catch(e){notice.value=String(e);}finally{busy.value=false;}}
function move(step:number){const i=filtered.value.findIndex(r=>r.id===selected.value?.id);const r=filtered.value[i+step];if(r)select(r);}
function date(v:any){return v?new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';}
</script>
<template><div class="growth-workspace">
 <div class="intro"><div><h2>成长分析</h2><p>基于正式发布的评价结果，核对成员成长报告。</p></div><label>评价周期 <select v-model="cycleId"><option v-for="c in cycles" :key="c.id" :value="c.id">{{c.title}}</option></select></label></div>
 <nav class="tabs"><button :class="{active:tab==='member'}" @click="tab='member'">成员报告</button><button :class="{active:tab==='organization'}" @click="tab='organization'">组织主题分析</button></nav>
 <template v-if="tab==='member'"><div class="stats"><div><span>分析对象</span><strong>{{counts.total}}</strong></div><div><span>待核对</span><strong>{{counts.pending}}</strong></div><div><span>已核对并展示</span><strong>{{counts.confirmed}}</strong></div></div>
 <div class="filters"><label>部门 <select v-model="department"><option value="">全部部门</option><option v-for="d in departments" :key="d" :value="d">{{d}}</option></select></label><input v-model="search" placeholder="搜索成员姓名" aria-label="搜索成员姓名"><label>状态 <select v-model="filter"><option value="ALL">全部状态</option><option v-for="(label,key) in statusLabel" :key="key" :value="key">{{label}}</option></select></label></div>
 <p v-if="notice" role="status" class="notice">{{notice}}</p><div class="columns"><section class="panel members"><div class="member-head"><span>成员</span><span>部门</span><span>分析状态</span></div><p v-if="loading">正在加载报告…</p><p v-else-if="!filtered.length">暂无符合条件的已发布结果</p><button v-for="r in filtered" :key="r.id" class="member" :class="{selected:selected?.id===r.id}" @click="select(r)"><span><b>{{r.display_name}}</b><small>{{date(r.updated)}}</small></span><span>{{r.department_name||'—'}}</span><span class="badge" :class="r.growthStatus">{{statusLabel[r.growthStatus]||r.growthStatus}}</span></button></section>
 <section class="panel report" v-if="selected"><header><div><h3>{{selected.display_name}} <small>{{selected.department_name||'—'}} · 发布版本 {{selected.publication_version}}</small></h3><span class="badge" :class="selected.growthStatus">{{statusLabel[selected.growthStatus]}}</span></div><div><button class="btn" @click="move(-1)">上一个</button> <button class="btn" @click="move(1)">下一个</button></div></header>
 <p v-if="!state">无法读取该成员的成长分析，请检查授权或重试。</p><template v-else><div class="report-actions"><span>成长报告</span><button class="btn" :disabled="busy||!state.configured" @click="generate">{{busy?'处理中…':state.items?.length?'重新生成':'生成报告'}}</button></div><p v-if="!state.configured">AI 服务尚未配置，无法生成报告。</p><p v-if="selected.growthStatus==='FAILED'">生成失败：{{state.items?.[0]?.failure_code}}，可检查配置及材料后重试。</p><p v-if="!state.items?.length">尚未生成成长报告。</p>
 <template v-if="draft.overall_summary"><div class="block"><h4>AI 成长画像</h4><textarea v-model="draft.overall_summary" :disabled="busy||!currentDraft" maxlength="180" /></div><div class="detail-grid"><div v-for="(label,key) in labels" :key="key" class="block"><h4>{{label}}</h4><p v-if="!draft[key]?.length">暂无数据</p><label v-for="(claim,index) in draft[key]" :key="index"><small>{{claim.dimension||'分析条目'}} · 依据 {{claim.evidence_ids?.join('、')||'—'}}</small><textarea v-model="claim.text" :disabled="busy||!currentDraft" maxlength="800" /></label></div></div><div class="block"><h4>趋势解读</h4><textarea v-model="draft.trend_summary" :disabled="busy||!currentDraft" maxlength="1000" /></div></template>
 <template v-else-if="currentDraft || selected.growthStatus==='CONFIRMED'"><div class="detail-grid"><div v-for="(label,key) in legacy" :key="key" class="block"><h4>{{label}}</h4><textarea v-model="draft[key]" :disabled="busy||!currentDraft" maxlength="4000" /></div></div></template>
 <details v-if="state.items?.length"><summary>材料依据与历史版本</summary><div v-for="g in state.items" :key="g.id"><p>生成 {{g.generation_no}} · {{statusLabel[g.status]||g.status}} · {{date(g.confirmed_at||g.created_at)}}</p><pre>{{g.input_snapshot}}</pre><p v-if="g.failure_code">{{g.failure_code}}</p></div></details><div v-if="currentDraft" class="footer"><span>编辑内容将在确认时保存并展示给成员。</span><button class="btn btn-primary" :disabled="busy||selected.target_id===auth.user?.id" @click="confirm">确认展示给成员</button></div></template></section><section v-else class="panel empty">请选择一位成员查看成长报告</section></div></template><section v-else class="panel empty">暂无可用的组织主题分析数据</section></div></template>
<style scoped>
.growth-workspace{color:#172e52}.intro{display:flex;justify-content:space-between;gap:20px;align-items:center}.intro h2{margin:0;font-size:24px}.intro p,.notice{color:#647896}.intro p{margin:8px 0 16px}.tabs{display:flex;gap:28px;border-bottom:1px solid #dce5f2;margin-bottom:18px}.tabs button{border:0;background:none;padding:12px 4px;color:#667a95;cursor:pointer}.tabs button.active{color:#2667ee;border-bottom:2px solid #2667ee;font-weight:600}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.stats>div{background:white;border:1px solid #e0e9f5;border-radius:10px;padding:18px 22px;display:flex;align-items:center;justify-content:space-between}.stats span{color:#657792}.stats strong{font-size:24px}.filters{display:flex;gap:14px;align-items:center;margin:18px 0;flex-wrap:wrap}.filters label,.intro label{display:flex;align-items:center;gap:8px;color:#61738c}select,input{height:38px;border:1px solid #d9e3f0;border-radius:6px;background:#fff;padding:0 10px;color:#253b5e}input{min-width:220px}.columns{display:grid;grid-template-columns:minmax(280px,34%) minmax(0,1fr);gap:16px;align-items:start}.panel{background:#fff;border:1px solid #e1e8f2;border-radius:10px;padding:20px;min-width:0}.member-head,.member{display:grid;grid-template-columns:1fr .8fr .85fr;gap:8px;align-items:center}.member-head{color:#77879e;font-size:12px;padding:10px}.member{width:100%;border:0;background:#fff;text-align:left;padding:14px 10px;color:inherit;cursor:pointer;border-bottom:1px solid #eef2f7}.member:hover,.member.selected{background:#eff5ff}.member small{display:block;color:#8796aa;margin-top:6px}.badge{display:inline-block;width:max-content;max-width:100%;border-radius:12px;padding:4px 8px;background:#eef2f7;color:#63758c;font-size:12px}.badge.DRAFT{background:#fff2dc;color:#c57d11}.badge.CONFIRMED{background:#e5f7ed;color:#258753}.badge.FAILED{background:#fff0f0;color:#c44}.report header{display:flex;justify-content:space-between;align-items:start;gap:12px}.report h3{margin:0 0 8px}.report h3 small{font-size:12px;color:#8796aa;font-weight:normal}.report-actions{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e8eef6;margin:16px 0;padding-bottom:12px;color:#2667ee;font-weight:600}.block{background:#f7f9fc;border-radius:8px;padding:14px;margin:12px 0}.block h4{margin:0 0 8px}.detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.detail-grid .block{margin:0}.block small{color:#7a8da6}textarea{display:block;width:100%;box-sizing:border-box;min-height:70px;margin:8px 0;border:1px solid #dce4ef;border-radius:6px;padding:10px;font:inherit;resize:vertical}textarea:disabled{background:transparent;border-color:transparent;color:#253b5e}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:18px;color:#70819b;font-size:12px}.empty{text-align:center;color:#8290a3;padding:80px 20px}@media(max-width:900px){.columns{grid-template-columns:1fr}.stats{grid-template-columns:repeat(3,1fr)}.intro{align-items:start;flex-direction:column}.detail-grid{grid-template-columns:1fr}}@media(max-width:550px){.stats{grid-template-columns:1fr}.filters input{min-width:0;width:100%}}
</style>
